// ParseEvent parses the body of an event notification and returns the
// state variables it carries, each as its own type
// (e.g. deviceproperties.SettingsReplicationState).
// Properties that cannot be decoded are skipped: the others are returned
// together with an error describing the failures.
func (s *Service) ParseEvent(body []byte) ([]any, error) {
	var set propertySet
	if err := xml.Unmarshal(body, &set); err != nil {
		return nil, err
	}
	var events []any
	var errs []error
	for _, raw := range set.Properties {
		var p property
		doc := append(append([]byte("<property>"), raw.Inner...), "</property>"...)
		if err := xml.Unmarshal(doc, &p); err != nil {
			errs = append(errs, fmt.Errorf("property %s: %w", propertyName(raw.Inner), err))
			continue
		}
		switch {
		case p.SettingsReplicationState != nil:
			events = append(events, *p.SettingsReplicationState)
		case p.ZoneName != nil:
			events = append(events, *p.ZoneName)
		case p.Icon != nil:
			events = append(events, *p.Icon)
		case p.Configuration != nil:
			events = append(events, *p.Configuration)
		case p.Invisible != nil:
			events = append(events, *p.Invisible)
		case p.IsZoneBridge != nil:
			events = append(events, *p.IsZoneBridge)
		case p.AirPlayEnabled != nil:
			events = append(events, *p.AirPlayEnabled)
		case p.SupportsAudioIn != nil:
			events = append(events, *p.SupportsAudioIn)
		case p.SupportsAudioClip != nil:
			events = append(events, *p.SupportsAudioClip)
		case p.IsIdle != nil:
			events = append(events, *p.IsIdle)
		case p.MoreInfo != nil:
			events = append(events, *p.MoreInfo)
		case p.ChannelMapSet != nil:
			events = append(events, *p.ChannelMapSet)
		case p.HTSatChanMapSet != nil:
			events = append(events, *p.HTSatChanMapSet)
		case p.HTBondedZoneCommitState != nil:
			events = append(events, *p.HTBondedZoneCommitState)
		case p.Orientation != nil:
			events = append(events, *p.Orientation)
		case p.LastChangedPlayState != nil:
			events = append(events, *p.LastChangedPlayState)
		case p.RoomCalibrationState != nil:
			events = append(events, *p.RoomCalibrationState)
		case p.AvailableRoomCalibration != nil:
			events = append(events, *p.AvailableRoomCalibration)
		case p.TVConfigurationError != nil:
			events = append(events, *p.TVConfigurationError)
		case p.HdmiCecAvailable != nil:
			events = append(events, *p.HdmiCecAvailable)
		case p.WirelessMode != nil:
			events = append(events, *p.WirelessMode)
		case p.WirelessLeafOnly != nil:
			events = append(events, *p.WirelessLeafOnly)
		case p.ConnectionType != nil:
			events = append(events, *p.ConnectionType)
		case p.HasConfiguredSSID != nil:
			events = append(events, *p.HasConfiguredSSID)
		case p.ChannelFreq != nil:
			events = append(events, *p.ChannelFreq)
		case p.BehindWifiExtender != nil:
			events = append(events, *p.BehindWifiExtender)
		case p.WifiEnabled != nil:
			events = append(events, *p.WifiEnabled)
		case p.EthLink != nil:
			events = append(events, *p.EthLink)
		case p.ConfigMode != nil:
			events = append(events, *p.ConfigMode)
		case p.SecureRegState != nil:
			events = append(events, *p.SecureRegState)
		case p.VoiceConfigState != nil:
			events = append(events, *p.VoiceConfigState)
		case p.MicEnabled != nil:
			events = append(events, *p.MicEnabled)
		case p.SvcActive != nil:
			events = append(events, *p.SvcActive)
		case p.AlexaCBLSupported != nil:
			events = append(events, *p.AlexaCBLSupported)
		}
	}
	return events, errors.Join(errs...)
}

// propertyName returns the name of the first element in a property's XML.
func propertyName(inner []byte) string {
	d := xml.NewDecoder(bytes.NewReader(inner))
	for {
		tok, err := d.Token()
		if err != nil {
			return "?"
		}
		if se, ok := tok.(xml.StartElement); ok {
			return se.Name.Local
		}
	}
}
